"""PostgreSQL access helpers (psycopg 3, no pool dependency).

Prisma conventions to keep in mind when writing raw SQL:
  * Table and column names are quoted PascalCase / camelCase ("AgentRun"."agentKey").
  * `@default(cuid())` ids are generated by the Prisma client, NOT the DB, so rows
    inserted from Python must supply their own id (`generate_id()`).
  * `@updatedAt` has no DB default either -> set "updatedAt" explicitly.
  * `DateTime` columns are `timestamp(3) without time zone` holding UTC values ->
    always pass naive UTC datetimes (`to_utc_naive`).

Per ADR-034 the Python side only writes DomainEvent status, AgentRun rows and
AgentProposal rows; every other mutation goes through the Next.js Internal API.
"""

from __future__ import annotations

import logging
import uuid
from contextlib import asynccontextmanager
from datetime import datetime, timezone
from typing import Any, AsyncIterator, Optional

import psycopg
from psycopg.rows import dict_row
from psycopg.types.json import Jsonb

from src.config import settings

logger = logging.getLogger("agent.db")


def generate_id() -> str:
    """cuid-like id (25 chars, starts with 'c') for rows inserted outside Prisma."""
    return "c" + uuid.uuid4().hex[:24]


def to_utc_naive(dt: datetime) -> datetime:
    """Convert an aware datetime to naive UTC (Prisma `timestamp(3)` storage format).

    Naive inputs are assumed to already be UTC and returned unchanged.
    """
    if dt.tzinfo is None:
        return dt
    return dt.astimezone(timezone.utc).replace(tzinfo=None)


def to_json(value: Any) -> Optional[Jsonb]:
    """Wrap a Python value for a Prisma `Json` column (None stays SQL NULL)."""
    return None if value is None else Jsonb(value)


async def connect(conninfo: Optional[str] = None) -> psycopg.AsyncConnection:
    """Open a new async connection with dict rows."""
    return await psycopg.AsyncConnection.connect(
        conninfo if conninfo is not None else settings.conninfo,
        row_factory=dict_row,
        connect_timeout=settings.DB_CONNECT_TIMEOUT_SECONDS,
    )


@asynccontextmanager
async def get_db_connection(conninfo: Optional[str] = None) -> AsyncIterator[psycopg.AsyncConnection]:
    """Per-operation connection. Commits on success, rolls back on error, always closes."""
    conn = await connect(conninfo)
    async with conn:
        yield conn


async def check_connection(conninfo: Optional[str] = None) -> bool:
    """Startup probe: returns True if the database answers `SELECT 1`."""
    try:
        async with get_db_connection(conninfo) as conn:
            cur = await conn.execute("SELECT 1 AS ok")
            row = await cur.fetchone()
            return bool(row and row["ok"] == 1)
    except (psycopg.Error, OSError) as exc:
        logger.error("Database connection check failed: %s", exc)
        return False
